#!/usr/bin/env bash
# After a push to the target branch left .devin/wiki.json stale, put the
# regenerated files on a fixed branch and open (or refresh) a pull request.
#
# The sync branch only ever changes files under .devin/, so new commits go on
# top of it with a plain push (no force push, no merge): its diff against the
# target branch stays limited to those files even when its base is older.
set -euo pipefail

: "${BASE_BRANCH:?BASE_BRANCH is required}"
: "${GH_TOKEN:?GH_TOKEN is required}"
SYNC_BRANCH="${SYNC_BRANCH:-deepwiki-wiki-sync/${BASE_BRANCH}}"
FILES=(.devin/wiki.json .devin/wiki-sync.lock.json)

[ -d .devin ] && git add -- "${FILES[@]}"
if git diff --cached --quiet; then
  echo "No changes to commit."
  exit 0
fi

saved="$(mktemp -d)"
cp "${FILES[@]}" "$saved/"
git reset -q --hard

if git fetch -q --depth 1 origin "refs/heads/${SYNC_BRANCH}" 2>/dev/null; then
  git checkout -q -B "$SYNC_BRANCH" FETCH_HEAD
else
  git checkout -q -B "$SYNC_BRANCH"
fi
mkdir -p .devin
cp "$saved"/* .devin/
git add -- "${FILES[@]}"

if git diff --cached --quiet; then
  echo "Branch ${SYNC_BRANCH} already holds this update."
else
  git -c user.name="${GIT_AUTHOR_NAME:-github-actions[bot]}" \
      -c user.email="${GIT_AUTHOR_EMAIL:-41898282+github-actions[bot]@users.noreply.github.com}" \
      commit -q -m "chore(deepwiki): update .devin/wiki.json"
  git push -q origin "HEAD:refs/heads/${SYNC_BRANCH}"
  echo "Pushed the update to ${SYNC_BRANCH}."
fi

existing="$(gh pr list --head "$SYNC_BRANCH" --base "$BASE_BRANCH" --state open \
  --json number --jq '.[0].number // empty')"
if [ -n "$existing" ]; then
  echo "Updated existing pull request #${existing}."
  exit 0
fi

gh pr create --base "$BASE_BRANCH" --head "$SYNC_BRANCH" \
  --title "chore(deepwiki): update .devin/wiki.json" \
  --body "The repository structure on \`${BASE_BRANCH}\` changed after the last \`.devin/wiki.json\` update (for example, a pull request was merged before its update finished). This pull request regenerates the DeepWiki page plan.

Generated by deepwiki-wiki-sync. Review the page list, then merge."
